import {useEffect, useRef, useCallback, useState} from 'react'
import {Button} from '@primer/react'
import {FoldIcon, UnfoldIcon} from '@primer/octicons-react'

export interface CustomCopilotCodeReviewCommentProps {
  numberOfTotalLines: number
}

export function CustomCopilotCodeReviewComment({numberOfTotalLines}: CustomCopilotCodeReviewCommentProps) {
  const buttonRef = useRef<HTMLButtonElement>(null)
  const buttonTextRef = useRef<HTMLSpanElement>(null)
  const [expanded, setExpanded] = useState(false)

  const handleClick = useCallback(() => {
    const button = buttonRef.current
    const buttonText = buttonTextRef.current

    const commentBody = button?.closest('.js-comment-body')
    const blobWrapper = commentBody?.querySelector('.blob-wrapper')

    if (!button || !blobWrapper || !buttonText) return

    const isExpanded = blobWrapper.classList.contains('expanded')
    // Get the button's current viewport offset (distance from top of viewport)
    const buttonRect = button.getBoundingClientRect()
    const buttonViewportOffset = buttonRect.top
    blobWrapper.classList.toggle('expanded')
    setExpanded(!isExpanded)

    if (isExpanded) {
      // Collapsing
      buttonText.textContent = `View all ${numberOfTotalLines} lines`
    } else {
      // Expanding
      buttonText.textContent = 'Show less'
    }

    // After the DOM updates, restore the button to the same viewport position
    requestAnimationFrame(() => {
      if (!button) return
      const buttonRectAfter = button.getBoundingClientRect()
      const newButtonViewportOffset = buttonRectAfter.top
      const scrollAdjustment = newButtonViewportOffset - buttonViewportOffset
      window.scrollBy({
        top: scrollAdjustment,
        behavior: 'instant',
      })
    })
  }, [numberOfTotalLines])

  useEffect(() => {
    if (buttonTextRef.current) {
      buttonTextRef.current.textContent = `View all ${numberOfTotalLines} lines`
    }
  }, [numberOfTotalLines])

  return (
    <div className="mt-0 mr-auto mb-2 mb-sm-1 mb-md-1 mb-lg-1 ml-0 ml-sm-0 ml-md-0 ml-lg-1">
      <Button
        ref={buttonRef}
        onClick={handleClick}
        leadingVisual={expanded ? FoldIcon : UnfoldIcon}
        variant="invisible"
        size="small"
      >
        <span ref={buttonTextRef}>View all {numberOfTotalLines} lines</span>
      </Button>
    </div>
  )
}
